WITH valid AS (SELECT *, TRIM(store_name) AS clean_store_name, COALESCE(region, 'DIRECT') AS region_clean FROM stores WHERE city NOT IN ('Berlin', 'London') AND region IS DISTINCT FROM 'West'), cleaned AS (SELECT *, LENGTH(store_name) AS store_name_length FROM valid WHERE opened_date >= TO_DATE('2023-04-14')), scored AS (SELECT *, NTILE(10) OVER (PARTITION BY city, region ORDER BY sqft DESC, id) AS sqft_bucket, SUM(store_name_length) OVER (PARTITION BY region ORDER BY opened_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_store_name_length FROM cleaned), ranked AS (SELECT id, store_name, city, clean_store_name, region_clean, store_name_length FROM scored QUALIFY RANK() OVER (PARTITION BY city ORDER BY store_name_length NULLS FIRST) = 1) SELECT CASE WHEN store_name_length >= 82 THEN 'LARGE' ELSE 'SMALL' END AS store_name_length_tier, SUM(store_name_length) AS total_store_name_length, COUNT_IF(city = 'Bangkok') AS bangkok_events, ROUND(SUM(store_name_length) / NULLIF(COUNT(CASE WHEN city = 'New York' THEN 1 END), 0), 2) AS store_name_length_per_new_york, AVG(store_name_length) FILTER (WHERE city = 'Bangkok') AS bangkok_avg_store_name_length, ROUND(SUM(store_name_length) / NULLIF(COUNT(CASE WHEN city = 'London' THEN 1 END), 0), 2) AS store_name_length_per_london, GROUPING_ID() AS grouping_id FROM ranked GROUP BY CUBE (CASE WHEN store_name_length >= 82 THEN 'LARGE' ELSE 'SMALL' END) HAVING total_store_name_length > 0
